const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// ======================================================\n// ROOT PRISMA SETUP (Prisma 7 compatible)\n// ======================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ======================================================\n// ENUMS\n// ======================================================\n\nenum Gender {\n  MALE\n  FEMALE\n  BINARY\n}\n\nenum Role {\n  PATIENT\n  DOCTOR\n  ADMIN\n}\n\nenum Specialty {\n  CARDIOLOGIST\n  DERMATOLOGIST\n  PEDIATRICIAN\n  NEUROLOGIST\n  NEPHROLOGIST\n  GASTROENTEROLOGIST\n  ENDOCRINOLOGIST\n  PULMONOLOGIST\n  ONCOLOGIST\n  ORTHOPEDIC\n  OPHTHALMOLOGIST\n  OTOLARYNGOLOGIST\n  UROLOGIST\n  RHEUMATOLOGIST\n  PSYCHIATRIST\n  PSYCHOLOGIST\n  GENERAL_PHYSICIAN\n  GENERAL_SURGEON\n  RADIOLOGIST\n  PATHOLOGIST\n  HEMATOLOGIST\n  DENTIST\n  GYNECOLOGIST\n  OBSTETRICIAN\n  PLASTIC_SURGEON\n  VASCULAR_SURGEON\n  CARDIOTHORACIC_SURGEON\n  DERMATOSURGEON\n  INFECTIOUS_DISEASE_SPECIALIST\n  IMMUNOLOGIST\n  ANESTHESIOLOGIST\n  EMERGENCY_MEDICINE\n  SPORTS_MEDICINE\n  PAIN_MEDICINE\n  CRITICAL_CARE\n  PHYSIOTHERAPIST\n  NUTRITIONIST\n}\n\nenum AgentApprovalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  EXPIRED\n}\n\nenum AgentExecutionStatus {\n  NOT_STARTED\n  EXECUTING\n  COMPLETED\n  FAILED\n}\n\nenum AgentActionRiskLevel {\n  LOW_AUTONOMOUS\n  MEDIUM_HUMAN_APPROVAL\n  HIGH_CLINICAL_RESTRICTED\n}\n\nenum MedicalPipelineStatus {\n  PENDING\n  QUEUED\n  RUNNING\n  PARTIAL\n  COMPLETED\n  RETRYABLE\n  FAILED\n  REVOKED\n}\n\nenum AgentThreadStatus {\n  ACTIVE\n  ARCHIVED\n  REDACTED\n}\n\nenum AgentMessageRole {\n  USER\n  ASSISTANT\n  TOOL\n  SYSTEM\n}\n\nenum AgentMessageStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  REDACTED\n}\n\nenum Qualification {\n  MBBS\n  BDS\n  BPT\n  BHMS\n  BAMS\n  MD\n  MS\n  DNB\n  MDS\n  DM\n  MCH\n  MPH\n  MBA_HM\n  PHD\n  DO\n  FELLOWSHIP\n  PGD\n}\n\nenum SlotStatus {\n  AVAILABLE\n  HELD\n  BOOKED\n  UNAVAILABLE\n  CANCELLED\n  ON_LEAVE\n}\n\nenum AppointmentStatus {\n  PENDING\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n  RESCHEDULED\n  EXPIRED\n}\n\nenum PaymentMethod {\n  OFFLINE\n  ONLINE\n}\n\nenum MedicalDocumentType {\n  LAB_REPORT\n  PRESCRIPTION\n  RADIOLOGY_SCAN\n  DISCHARGE_SUMMARY\n  MEDICAL_CERTIFICATE\n  VACCINATION_RECORD\n  OTHER\n}\n\nenum MedicalDocumentProcessingStatus {\n  PENDING\n  QUEUED\n  PROCESSING\n  READY\n  FAILED\n}\n\n// ======================================================\n// USER, ADMIN, DOCTOR, PATIENT MODELS\n// ======================================================\n\nmodel User {\n  id       String @id @default(cuid())\n  email    String @unique\n  phoneNo  String\n  name     String\n  password String\n  age      Int\n\n  gender Gender @default(MALE)\n  role   Role   @default(PATIENT)\n\n  address String\n\n  pinCode Int\n\n  profileImageUrl         String?\n  emailVerified           Boolean              @default(false)\n  isActive                Boolean              @default(true)\n  admin                   Admin?\n  doctor                  Doctor?\n  patient                 Patient?\n  otp                     Otp[]\n  accessLogs              AccessLog[]\n  auditLogs               AuditLog[]\n  chatMessages            ChatMessages[]\n  payments                Payment[]\n  checkouts               Checkout[]\n  notifications           Notification[]\n  agentThreadsOwned       AgentThread[]        @relation(\"AgentThreadOwner\")\n  agentApprovalsRequested AgentApproval[]      @relation(\"AgentApprovalRequester\")\n  agentApprovalsDecided   AgentApproval[]      @relation(\"AgentApprovalDecider\")\n  medicalGrantsCreated    MedicalAccessGrant[] @relation(\"MedicalGrantCreator\")\n\n  updatedAt    DateTime      @updatedAt\n  createdAt    DateTime      @default(now())\n  location     Location      @relation(fields: [pinCode], references: [pincode])\n  bankAccounts BankAccount[]\n}\n\nmodel Location {\n  pincode Int    @id @unique\n  city    String\n  state   String\n\n  user User[]\n}\n\nmodel Admin {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  managerId String?\n  manager   Admin?  @relation(\"AdminHierarchy\", fields: [managerId], references: [id], onDelete: Cascade)\n  subAdmins Admin[] @relation(\"AdminHierarchy\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([managerId])\n}\n\nmodel Doctor {\n  isReleaseFixture Boolean   @default(false)\n  id               String    @id @default(cuid())\n  userId           String    @unique\n  specialty        Specialty\n  experience       Int       @default(0)\n  fees             Int       @default(0)\n  doctorBio        String?\n  balance          Int       @default(0)\n  // A one-time saved practice location. Patient locations are never stored.\n  latitude         Float?    @db.DoublePrecision\n  longitude        Float?    @db.DoublePrecision\n\n  user                User                    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  leaves              Leave[]\n  schedule            Schedule?\n  patientRelations    DoctorPatientRelation[]\n  appointments        Appointment[]\n  slots               Slot[]\n  checkouts           Checkout[]\n  comments            Comment[]\n  ratings             Rating[]\n  withdrawals         Withdrawal[]\n  agentThreads        AgentThread[]\n  medicalAccessGrants MedicalAccessGrant[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  doctorQualifications DoctorQualification[]\n\n  @@index([latitude, longitude])\n}\n\nmodel DoctorQualification {\n  id            String        @id @default(cuid())\n  doctorId      String\n  doctor        Doctor        @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  qualification Qualification\n\n  @@unique([doctorId, qualification])\n}\n\nmodel Patient {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  medicalHistory     String @default(\"\")\n  allergies          String @default(\"\")\n  currentMedications String @default(\"\")\n\n  user                  User                    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  doctorRelations       DoctorPatientRelation[]\n  appointments          Appointment[]\n  checkouts             Checkout[]\n  comments              Comment[]\n  ratings               Rating[]\n  medicalDocuments      MedicalDocument[]\n  agentThreads          AgentThread[]\n  medicalAccessGrants   MedicalAccessGrant[]\n  extractedObservations MedicalObservation[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel MedicalDocument {\n  id String @id @default(cuid())\n\n  patientId String\n  patient   Patient @relation(fields: [patientId], references: [id], onDelete: Cascade)\n\n  title String\n  type  MedicalDocumentType\n\n  fileName String\n  mimeType String\n  fileSize Int\n\n  storagePath String @unique\n\n  reportDate       DateTime\n  hospitalOrDoctor String?\n  notes            String?\n\n  processingStatus MedicalDocumentProcessingStatus @default(PENDING)\n  processingError  String?\n  processedAt      DateTime?\n\n  versions        MedicalDocumentVersion[]\n  ingestionJobs   MedicalIngestionJob[]\n  accessGrants    MedicalAccessGrant[]\n  cleanupRequests MedicalDocumentCleanup[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([patientId])\n  @@index([patientId, reportDate])\n  @@index([patientId, type])\n  @@index([patientId, processingStatus])\n}\n\n// ======================================================\n// USER MODULE (Notification)\n// ======================================================\n\nmodel Notification {\n  id          String    @id @default(cuid())\n  userId      String\n  message     String\n  actionHref  String?\n  actionLabel String?\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  isRead      Boolean   @default(false)\n  status      String    @default(\"UNREAD\")\n  readAt      DateTime?\n  eventId     String?\n\n  createdAt DateTime @default(now())\n\n  @@unique([userId, eventId])\n  @@index([userId])\n}\n\n// ======================================================\n// DOCTOR MODULE (Leave, Schedule, Availability, Slot, Appointment)\n// ======================================================\n\nmodel Leave {\n  id       String @id @default(cuid())\n  doctorId String\n\n  doctor Doctor @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  reason    String\n  startDate DateTime\n  endDate   DateTime\n  applyAt   DateTime @default(now())\n\n  @@unique([doctorId, startDate, endDate])\n  @@index([doctorId])\n  @@index([startDate, endDate])\n}\n\nmodel Schedule {\n  id             String @id @default(cuid())\n  doctorId       String @unique\n  weeklySchedule Json\n\n  doctor Doctor @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([doctorId])\n}\n\nmodel Slot {\n  id              String     @id @default(cuid())\n  doctorId        String\n  date            DateTime   @db.Date\n  startTime       DateTime\n  endTime         DateTime\n  status          SlotStatus @default(AVAILABLE)\n  heldByPatientId String?\n  heldAt          DateTime?\n  holdToken       String?\n  holdExpiresAt   DateTime?\n\n  appointments Appointment[]\n  checkouts    Checkout[]\n\n  doctor    Doctor   @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([doctorId, date, startTime])\n  @@index([doctorId, date, status])\n  @@index([startTime, status])\n  @@index([heldByPatientId])\n  @@index([holdExpiresAt])\n}\n\nmodel Appointment {\n  id                   String            @id @default(cuid())\n  doctorId             String\n  patientId            String\n  slotId               String\n  paymentId            String?           @unique\n  status               AppointmentStatus @default(PENDING)\n  paymentMethod        PaymentMethod     @default(OFFLINE)\n  transactionId        String?\n  notes                String?\n  bookedAt             DateTime          @default(now())\n  updatedAt            DateTime          @updatedAt\n  slot                 Slot              @relation(fields: [slotId], references: [id])\n  payment              Payment?          @relation(fields: [paymentId], references: [id])\n  checkout             Checkout?\n  doctor               Doctor            @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  patient              Patient           @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  isAppointmentOffline Boolean           @default(true)\n\n  @@index([doctorId, patientId])\n  @@index([slotId])\n  @@index([status])\n}\n\n// ======================================================\n// DOCTOR–PATIENT RELATION MODEL / CHAT MODEL\n// ======================================================\n\nmodel DoctorPatientRelation {\n  id             String @id @default(cuid())\n  doctorsUserId  String\n  patientsUserId String\n\n  doctorLastReadAt  DateTime?\n  patientLastReadAt DateTime?\n\n  chatMessages ChatMessages[]\n\n  doctor  Doctor  @relation(fields: [doctorsUserId], references: [userId], onDelete: Cascade)\n  patient Patient @relation(fields: [patientsUserId], references: [userId], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([doctorsUserId, patientsUserId])\n  @@index([patientsUserId])\n  @@index([doctorsUserId])\n}\n\nmodel ChatMessages {\n  id String @id @default(cuid())\n\n  doctorPatientRelationId String\n  doctorPatientRelation   DoctorPatientRelation @relation(fields: [doctorPatientRelationId], references: [id], onDelete: Cascade)\n\n  text            String\n  senderId        String\n  sender          User    @relation(fields: [senderId], references: [id], onDelete: Cascade)\n  clientMessageId String? @unique\n\n  isRead Boolean   @default(false)\n  readAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([doctorPatientRelationId, createdAt])\n  @@index([doctorPatientRelationId, isRead])\n  @@index([senderId])\n}\n\nmodel Payment {\n  id             String  @id @default(cuid())\n  idempotencyKey String? @unique\n  amount         Int\n  currency       String  @default(\"INR\")\n  userId         String\n  doctorId       String?\n  slotId         String?\n  holdToken      String?\n  user           User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  status            String\n  razorpayOrderId   String    @unique\n  razorpayPaymentId String?   @unique\n  capturedAt        DateTime?\n  leaseExpiresAt    DateTime?\n  leaseOwner        String?\n  attempts          Int       @default(0)\n  nextAttemptAt     DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @default(now()) @updatedAt\n\n  appointment   Appointment?\n  checkout      Checkout?\n  refunds       Refund[]\n  webhookEvents WebhookEvent[]\n\n  @@index([userId, status])\n  @@index([slotId])\n  @@index([razorpayPaymentId])\n  @@index([status, nextAttemptAt])\n}\n\nenum CheckoutStatus {\n  PENDING_ORDER\n  READY_FOR_PAYMENT\n  CONFIRMED\n  EXPIRED\n  FAILED\n  UNRESOLVED\n  MANUAL_REVIEW\n}\n\nmodel Checkout {\n  id             String         @id @default(cuid())\n  idempotencyKey String         @unique\n  userId         String\n  patientId      String\n  doctorId       String\n  slotId         String\n  holdToken      String\n  paymentMethod  PaymentMethod  @default(ONLINE)\n  amount         Int // Immutable amount in paise\n  currency       String         @default(\"INR\")\n  status         CheckoutStatus @default(PENDING_ORDER)\n\n  razorpayOrderId   String?  @unique\n  providerReference String?\n  expiresAt         DateTime\n\n  paymentId     String? @unique\n  appointmentId String? @unique\n\n  // Processing, lease & reconciliation tracking\n  processingStartedAt DateTime?\n  leaseExpiresAt      DateTime?\n  leaseOwner          String?\n  attempts            Int       @default(0)\n  lastAttemptAt       DateTime?\n  nextAttemptAt       DateTime?\n  lastError           String?\n\n  user        User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  patient     Patient      @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  doctor      Doctor       @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  slot        Slot         @relation(fields: [slotId], references: [id], onDelete: Cascade)\n  payment     Payment?     @relation(fields: [paymentId], references: [id], onDelete: SetNull)\n  appointment Appointment? @relation(fields: [appointmentId], references: [id], onDelete: SetNull)\n\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  confirmedAt DateTime?\n\n  @@index([userId, status])\n  @@index([doctorId, slotId])\n  @@index([expiresAt, status])\n  @@index([razorpayOrderId])\n  @@index([providerReference])\n  @@index([status, nextAttemptAt])\n}\n\nenum RefundStatus {\n  PENDING\n  PROCESSING\n  PROCESSED\n  FAILED\n}\n\nmodel Refund {\n  id               String       @id @default(cuid())\n  paymentId        String\n  payment          Payment      @relation(fields: [paymentId], references: [id], onDelete: Cascade)\n  amount           Int // Amount in paise\n  currency         String       @default(\"INR\")\n  reason           String\n  status           RefundStatus @default(PENDING)\n  idempotencyKey   String       @unique\n  razorpayRefundId String?      @unique\n  failureReason    String?\n  attempts         Int          @default(0)\n  lastAttemptAt    DateTime?\n  leaseExpiresAt   DateTime?\n  leaseOwner       String?\n  nextAttemptAt    DateTime?\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n  processedAt      DateTime?\n\n  @@index([paymentId])\n  @@index([status])\n  @@index([status, nextAttemptAt])\n}\n\nenum WebhookEventStatus {\n  RECEIVED\n  PROCESSING\n  PROCESSED\n  FAILED\n  IGNORED\n}\n\nmodel WebhookEvent {\n  id                  String             @id @default(cuid())\n  providerEventId     String             @unique\n  eventType           String\n  paymentId           String?\n  payment             Payment?           @relation(fields: [paymentId], references: [id], onDelete: SetNull)\n  status              WebhookEventStatus @default(RECEIVED)\n  payload             Json\n  processingError     String?\n  processingStartedAt DateTime?\n  leaseExpiresAt      DateTime?\n  leaseOwner          String?\n  attempts            Int                @default(0)\n  nextAttemptAt       DateTime?\n  receivedAt          DateTime           @default(now())\n  processedAt         DateTime?\n\n  @@index([status])\n  @@index([eventType])\n  @@index([paymentId])\n  @@index([status, nextAttemptAt])\n}\n\nenum OutboxStatus {\n  PENDING\n  PROCESSING\n  DELIVERED\n  FAILED\n}\n\nmodel NotificationOutbox {\n  id                  String       @id @default(cuid())\n  eventId             String       @unique\n  channel             String // e.g. \"SOCKET_NOTIFICATION\", \"SOCKET_APPOINTMENT_REQUEST\", \"SOCKET_APPOINTMENT_STATUS\"\n  targetUserId        String\n  payload             Json\n  status              OutboxStatus @default(PENDING)\n  attempts            Int          @default(0)\n  lastError           String?\n  lastAttemptAt       DateTime?\n  processingStartedAt DateTime?\n  leaseExpiresAt      DateTime?\n  leaseOwner          String?\n  nextAttemptAt       DateTime?\n  createdAt           DateTime     @default(now())\n  deliveredAt         DateTime?\n\n  @@index([status, createdAt])\n  @@index([targetUserId])\n  @@index([status, nextAttemptAt])\n}\n\nenum WithdrawalStatus {\n  PENDING\n  PROCESSING\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\nmodel Withdrawal {\n  id       String @id @default(cuid())\n  doctorId String\n  doctor   Doctor @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  amount   Int // Amount in paise\n  currency String           @default(\"INR\")\n  status   WithdrawalStatus @default(PENDING)\n\n  // Razorpay payout details (if using Razorpay for payouts)\n  razorpayPayoutId String?\n  failureReason    String?\n\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  processedAt DateTime?\n\n  @@index([doctorId])\n  @@index([status])\n}\n\nmodel BankAccount {\n  id                    String @id @default(cuid())\n  userId                String\n  user                  User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  bankAccountNumber     String @unique\n  bankIFSC              String\n  bankAccountHolderName String\n  bankName              String\n}\n\nmodel Otp {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  userId    String   @unique\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code      String\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n}\n\n// ======================================================\n// LOG MODELS\n// ======================================================\n\nmodel AccessLog {\n  id       String  @id @default(cuid())\n  userId   String?\n  targetId String?\n  action   String\n  tag      String? @default(\"SYSTEM\") // e.g. AUTH, APPOINTMENT, ADMIN\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([targetId])\n  @@index([tag])\n  @@index([createdAt])\n  @@index([userId, createdAt])\n}\n\nmodel AuditLog {\n  id       String  @id @default(cuid())\n  userId   String?\n  action   String\n  tag      String? @default(\"SYSTEM\") // e.g. AUTH, SECURITY, ONBOARDING\n  metadata Json?\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([tag])\n  @@index([createdAt])\n  @@index([userId, createdAt])\n}\n\n// ======================================================\n// DOCTOR REVIEW/COMMENT SYSTEM\n// ======================================================\n\nmodel Rating {\n  id        String @id @default(cuid())\n  doctorId  String\n  patientId String\n  rating    Int // 1-5 stars\n\n  // Relations\n  doctor  Doctor  @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  patient Patient @relation(fields: [patientId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([doctorId, patientId]) // One rating per user per doctor\n  @@index([doctorId])\n  @@index([patientId])\n}\n\nmodel Comment {\n  id        String @id @default(cuid())\n  doctorId  String\n  patientId String\n  text      String // Comment text\n\n  // Relations\n  doctor  Doctor  @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  patient Patient @relation(fields: [patientId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([doctorId])\n  @@index([patientId])\n  @@index([createdAt])\n}\n\n// -----------------------------------------------------------------------------\n// Ingestion: immutable versions, page geometry, source hierarchy, structured data\n// -----------------------------------------------------------------------------\n\nmodel MedicalDocumentVersion {\n  id                String                   @id @default(cuid())\n  documentId        String\n  document          MedicalDocument          @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  versionNumber     Int\n  sourceSha256      String\n  schemaVersion     String\n  pipelineVersion   String\n  configFingerprint String\n  tokenizerName     String?\n  extractionStatus  MedicalPipelineStatus    @default(PENDING)\n  indexStatus       MedicalPipelineStatus    @default(PENDING)\n  isPublished       Boolean                  @default(false)\n  pageCount         Int                      @default(0)\n  objectCount       Int                      @default(0)\n  chunkCount        Int                      @default(0)\n  issueCount        Int                      @default(0)\n  manifest          Json? // full NormalizedDocument metadata (pages/sections/config/issues)\n  pipelineMetadata  Json? // provider versions, model choices, budgets, actual capabilities\n  contentSha256     String?\n  createdAt         DateTime                 @default(now())\n  publishedAt       DateTime?\n  revokedAt         DateTime?\n  pages             MedicalDocumentPage[]\n  sections          MedicalDocumentSection[]\n  objects           MedicalDocumentObject[]\n  assets            MedicalDocumentAsset[]\n  chunks            MedicalDocumentChunk[]\n  observations      MedicalObservation[]\n  jobs              MedicalIngestionJob[]\n  issues            MedicalExtractionIssue[]\n\n  @@unique([documentId, versionNumber])\n  @@index([documentId, isPublished, revokedAt])\n  @@index([sourceSha256])\n}\n\nmodel MedicalIngestionJob {\n  id              String                  @id @default(cuid())\n  documentId      String\n  document        MedicalDocument         @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  versionId       String?\n  version         MedicalDocumentVersion? @relation(fields: [versionId], references: [id], onDelete: SetNull)\n  generation      Int                     @default(1)\n  status          MedicalPipelineStatus   @default(QUEUED)\n  stage           String                  @default(\"registered\")\n  attempts        Int                     @default(0)\n  availableAt     DateTime                @default(now())\n  startedAt       DateTime?\n  lastHeartbeatAt DateTime?\n  completedAt     DateTime?\n  leaseToken      String?\n  leaseOwner      String?\n  leaseExpiresAt  DateTime?\n  errorCode       String?\n  retryable       Boolean                 @default(false)\n  progress        Json?\n  resourceMetrics Json? // elapsed, peak RSS, provider usage, token counts\n  createdAt       DateTime                @default(now())\n  updatedAt       DateTime                @updatedAt\n\n  @@unique([documentId, generation])\n  @@index([status, availableAt])\n  @@index([leaseExpiresAt])\n}\n\nmodel MedicalDocumentPage {\n  id               String                 @id @default(cuid())\n  versionId        String\n  version          MedicalDocumentVersion @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  pageNumber       Int\n  width            Float\n  height           Float\n  rotation         Int                    @default(0)\n  selectableChars  Int                    @default(0)\n  coordinateSystem String                 @default(\"unrotated_pdf_points\")\n  cropbox          Json // [x0,y0,x1,y1]\n  pdfToPage        Json? // affine transform\n  status           MedicalPipelineStatus  @default(COMPLETED)\n  metadata         Json? // original validated Page model, warnings, provider IDs\n  regions          MedicalObjectRegion[]\n\n  @@unique([versionId, pageNumber])\n}\n\nmodel MedicalDocumentSection {\n  id              String                 @id @default(cuid())\n  versionId       String\n  version         MedicalDocumentVersion @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  sectionStableId String\n  parentSectionId String?\n  title           String\n  level           Int\n  headingPath     Json // ordered heading strings\n  source          Json // exact Search Sphere SourceRef\n  readingOrder    Int?\n\n  @@unique([versionId, sectionStableId])\n}\n\nmodel MedicalDocumentObject {\n  id              String                 @id @default(cuid())\n  versionId       String\n  version         MedicalDocumentVersion @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  objectStableId  String\n  kind            String // text | table | image | chart | diagram\n  subtype         String? // e.g. pie, bar, flowchart; NEVER assume verified\n  title           String?\n  text            String? // paragraph/native/combined searchable content, as appropriate\n  sectionStableId String?\n  headingPath     Json? // section ancestry\n  firstPage       Int?\n  lastPage        Int?\n  readingOrder    Int?\n  status          MedicalPipelineStatus  @default(PARTIAL)\n  reviewRequired  Boolean                @default(false)\n  confidence      Float?\n  normalized      Json // ENTIRE validated Paragraph/Table/Visual object, no field loss\n  sourceSha256    String?\n  createdAt       DateTime               @default(now())\n  regions         MedicalObjectRegion[]\n  assets          MedicalDocumentAsset[]\n  chunkLinks      MedicalChunkObject[]\n  observations    MedicalObservation[]\n\n  @@unique([versionId, objectStableId])\n  @@index([versionId, kind, firstPage])\n  @@index([sectionStableId])\n}\n\nmodel MedicalObjectRegion {\n  id               String                @id @default(cuid())\n  objectId         String\n  object           MedicalDocumentObject @relation(fields: [objectId], references: [id], onDelete: Cascade)\n  pageId           String\n  page             MedicalDocumentPage   @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  regionStableId   String\n  parentRegionId   String?\n  readingOrder     Int\n  coordinateSystem String\n  x0               Float\n  y0               Float\n  x1               Float\n  y1               Float\n  sourceImageId    String? // opaque authorized asset ID, not a public URL\n  provider         String?\n  model            String?\n  confidence       Float?\n  evidence         Json? // OCR, layout model and source-specific evidence markers\n  source           Json // full SourceRef JSON incl. page, bbox, section, offsets\n\n  @@unique([objectId, pageId, regionStableId])\n  @@index([pageId, readingOrder])\n}\n\nmodel MedicalDocumentAsset {\n  id            String                 @id @default(cuid())\n  versionId     String\n  version       MedicalDocumentVersion @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  objectId      String?\n  object        MedicalDocumentObject? @relation(fields: [objectId], references: [id], onDelete: SetNull)\n  kind          String // crop, page_preview, diagram_panel, image, etc.\n  opaqueAssetId String\n  storagePath   String                 @unique // Quick-Clinic PRIVATE object storage\n  mimeType      String\n  fileSize      Int\n  sha256        String\n  pageNumber    Int?\n  geometry      Json?\n  metadata      Json?\n  createdAt     DateTime               @default(now())\n  deletedAt     DateTime?\n\n  @@unique([versionId, opaqueAssetId])\n  @@index([objectId])\n}\n\nmodel MedicalExtractionIssue {\n  id             String                 @id @default(cuid())\n  versionId      String\n  version        MedicalDocumentVersion @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  pageNumber     Int?\n  objectStableId String?\n  stage          String\n  code           String\n  retryable      Boolean                @default(false)\n  details        Json? // sanitized diagnostic metadata, no raw credentials\n  createdAt      DateTime               @default(now())\n\n  @@index([versionId, stage, pageNumber])\n}\n\n// -----------------------------------------------------------------------------\n// Retrieval: version-bound chunks, source linkage, pgvector in THIS database\n// -----------------------------------------------------------------------------\n\nmodel MedicalDocumentChunk {\n  id              String                  @id @default(cuid())\n  versionId       String\n  version         MedicalDocumentVersion  @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  chunkStableId   String\n  chunkIndex      Int\n  kind            String // text, table, chart, diagram, image\n  content         String\n  contentSha256   String\n  tokenCount      Int\n  tokenizer       String\n  headingPath     Json?\n  sourceObjectIds Json // preserve stable source object IDs\n  paragraphIds    Json?\n  sentenceIds     Json?\n  pageNumbers     Json // sorted full page list\n  startPage       Int\n  endPage         Int\n  rowStart        Int?\n  rowEnd          Int?\n  isFragment      Boolean                 @default(false)\n  provenance      Json // exact SourceRef list + extraction provenance\n  pipelineVersion String\n  status          MedicalPipelineStatus   @default(COMPLETED)\n  createdAt       DateTime                @default(now())\n  sourceLinks     MedicalChunkObject[]\n  embeddings      MedicalChunkEmbedding[]\n  retrievalHits   AgentRetrievalHit[]\n  observations    MedicalObservation[]\n\n  @@unique([versionId, chunkStableId])\n  @@unique([versionId, chunkIndex])\n  @@index([versionId, kind, startPage])\n  @@index([contentSha256])\n}\n\nmodel MedicalChunkObject {\n  id         String                @id @default(cuid())\n  chunkId    String\n  chunk      MedicalDocumentChunk  @relation(fields: [chunkId], references: [id], onDelete: Cascade)\n  objectId   String\n  object     MedicalDocumentObject @relation(fields: [objectId], references: [id], onDelete: Cascade)\n  sourceRefs Json? // page boxes, sentence offsets, cell/row ranges\n  createdAt  DateTime              @default(now())\n\n  @@unique([chunkId, objectId])\n  @@index([objectId])\n}\n\nmodel MedicalChunkEmbedding {\n  id                String                      @id @default(cuid())\n  chunkId           String\n  chunk             MedicalDocumentChunk        @relation(fields: [chunkId], references: [id], onDelete: Cascade)\n  vectorId          String                      @unique // stable search/index identity\n  provider          String\n  model             String\n  dimension         Int                         @default(384)\n  embeddingVersion  String\n  indexGeneration   Int                         @default(1)\n  inputSha256       String\n  status            MedicalPipelineStatus       @default(PENDING)\n  embedding         Unsupported(\"vector(384)\")? // pgvector: created via SQL migration\n  embeddingMetadata Json?\n  indexedAt         DateTime?\n  createdAt         DateTime                    @default(now())\n\n  @@unique([chunkId, model, embeddingVersion])\n  @@index([status, model, dimension])\n}\n\nmodel MedicalObservation {\n  id                    String                 @id @default(cuid())\n  patientId             String\n  patient               Patient                @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  versionId             String\n  version               MedicalDocumentVersion @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  objectId              String?\n  object                MedicalDocumentObject? @relation(fields: [objectId], references: [id], onDelete: SetNull)\n  chunkId               String?\n  chunk                 MedicalDocumentChunk?  @relation(fields: [chunkId], references: [id], onDelete: SetNull)\n  observationType       String\n  displayName           String\n  valueNumeric          Float?\n  valueSecondaryNumeric Float?\n  valueText             String?\n  unit                  String?\n  referenceRange        Json?\n  observedAt            DateTime?\n  reportedAt            DateTime?\n  dateInferred          Boolean                @default(false)\n  pageNumber            Int?\n  extractionMethod      String\n  confidence            Float?\n  reviewStatus          String                 @default(\"UNREVIEWED\")\n  source                Json // values/cells/page/region/ocr evidence\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n\n  @@index([patientId, observationType, observedAt])\n  @@index([versionId, pageNumber])\n}\n\n// -----------------------------------------------------------------------------\n// Patient authorization, explicit grants/revocation, storage cleanup\n// -----------------------------------------------------------------------------\n\nmodel MedicalAccessGrant {\n  id                        String           @id @default(cuid())\n  patientId                 String\n  patient                   Patient          @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  doctorId                  String\n  doctor                    Doctor           @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  documentId                String?\n  document                  MedicalDocument? @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  grantedByUserId           String\n  grantedBy                 User             @relation(\"MedicalGrantCreator\", fields: [grantedByUserId], references: [id], onDelete: Restrict)\n  relationshipAppointmentId String?\n  scope                     Json // document/category and permitted operations; never trust without auth\n  consentSource             String\n  policyVersion             Int              @default(1)\n  effectiveAt               DateTime         @default(now())\n  expiresAt                 DateTime?\n  revokedAt                 DateTime?\n  revokedReason             String?\n  createdAt                 DateTime         @default(now())\n  updatedAt                 DateTime         @updatedAt\n\n  @@index([doctorId, patientId, revokedAt, expiresAt])\n  @@index([documentId])\n}\n\nmodel MedicalDocumentCleanup {\n  id                 String           @id @default(cuid())\n  documentId         String?\n  document           MedicalDocument? @relation(fields: [documentId], references: [id], onDelete: SetNull)\n  documentIdSnapshot String\n  storagePath        String // opaque private storage key; no extracted PHI\n  status             String           @default(\"QUEUED\")\n  attempts           Int              @default(0)\n  availableAt        DateTime         @default(now())\n  leaseToken         String?\n  leaseExpiresAt     DateTime?\n  lastErrorCode      String?\n  createdAt          DateTime         @default(now())\n  completedAt        DateTime?\n\n  @@index([status, availableAt])\n  @@index([documentIdSnapshot])\n}\n\n// -----------------------------------------------------------------------------\n// Agent: exact Q/A, scoped history, memory, tool and retrieval provenance\n// -----------------------------------------------------------------------------\n\nmodel AgentThread {\n  id                  String                @id @default(cuid()) // stable LangGraph thread_id\n  ownerUserId         String\n  owner               User                  @relation(\"AgentThreadOwner\", fields: [ownerUserId], references: [id], onDelete: Cascade)\n  doctorId            String?\n  doctor              Doctor?               @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  patientId           String?\n  patient             Patient?              @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  scopeType           String                @default(\"GENERAL\") // GENERAL or SINGLE_PATIENT\n  purpose             String                @default(\"CLINIC_ASSISTANT\")\n  title               String                @default(\"New conversation\")\n  status              AgentThreadStatus     @default(ACTIVE)\n  permissionRevision  Int                   @default(1)\n  latestMemoryVersion Int                   @default(0)\n  createdAt           DateTime              @default(now())\n  updatedAt           DateTime              @updatedAt\n  lastMessageAt       DateTime?\n  redactedAt          DateTime?\n  messages            AgentMessage[]\n  turns               AgentTurn[]\n  memories            AgentMemorySnapshot[]\n  approvals           AgentApproval[]\n  toolCalls           AgentToolCall[]\n  providerCalls       AgentModelCall[]\n\n  @@index([ownerUserId, status, updatedAt])\n  @@index([doctorId, patientId])\n}\n\nmodel AgentTurn {\n  id                 String              @id @default(cuid())\n  threadId           String\n  thread             AgentThread         @relation(fields: [threadId], references: [id], onDelete: Cascade)\n  turnIndex          Int\n  originalQuery      String\n  retrievalQuery     String?\n  rewritten          Boolean             @default(false)\n  requiresHistory    Boolean             @default(false)\n  queryRoute         String? // DIRECT, RAG, CLARIFICATION, etc.\n  queryPolicyVersion String?\n  classification     Json?\n  plannedTools       Json?\n  status             String              @default(\"RUNNING\")\n  responseHash       String?\n  startedAt          DateTime            @default(now())\n  completedAt        DateTime?\n  messages           AgentMessage[]\n  contextLinks       AgentContextLink[]\n  retrievalRuns      AgentRetrievalRun[]\n  toolCalls          AgentToolCall[]\n  providerCalls      AgentModelCall[]\n\n  @@unique([threadId, turnIndex])\n  @@index([threadId, startedAt])\n}\n\nmodel AgentMessage {\n  id              String                 @id @default(cuid())\n  threadId        String\n  thread          AgentThread            @relation(fields: [threadId], references: [id], onDelete: Cascade)\n  turnId          String?\n  turn            AgentTurn?             @relation(fields: [turnId], references: [id], onDelete: SetNull)\n  sequence        Int\n  role            AgentMessageRole\n  status          AgentMessageStatus     @default(COMPLETED)\n  content         String // original Q / assistant answer / safe tool message\n  contentSha256   String?\n  messageMetadata Json? // API request IDs, versions, app display info, token counts\n  createdAt       DateTime               @default(now())\n  redactedAt      DateTime?\n  redactionReason String?\n  citations       AgentMessageCitation[]\n  usedAsContext   AgentContextLink[]\n\n  @@unique([threadId, sequence])\n  @@index([turnId, createdAt])\n  @@index([threadId, createdAt])\n}\n\nmodel AgentContextLink {\n  id                 String       @id @default(cuid())\n  turnId             String\n  turn               AgentTurn    @relation(fields: [turnId], references: [id], onDelete: Cascade)\n  messageId          String\n  message            AgentMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  reason             String // recent_window, semantic_memory, previous_answer_reference\n  orderIndex         Int\n  permissionRevision Int\n  includedAt         DateTime     @default(now())\n\n  @@unique([turnId, messageId])\n  @@index([messageId])\n}\n\nmodel AgentMemorySnapshot {\n  id                 String      @id @default(cuid())\n  threadId           String\n  thread             AgentThread @relation(fields: [threadId], references: [id], onDelete: Cascade)\n  version            Int\n  summary            String\n  summarySha256      String\n  coveredMessageIds  Json // exact past messages summarized\n  sourceChunkIds     Json? // linked chunk/version IDs, not PHI copies\n  topics             Json?\n  latestMessageId    String?\n  tokenCount         Int         @default(0)\n  summarizerModel    String?\n  permissionRevision Int\n  authorizationHash  String?\n  createdAt          DateTime    @default(now())\n  invalidatedAt      DateTime?\n  invalidationReason String?\n\n  @@unique([threadId, version])\n  @@index([threadId, invalidatedAt])\n}\n\nmodel AgentRetrievalRun {\n  id                String              @id @default(cuid())\n  turnId            String\n  turn              AgentTurn           @relation(fields: [turnId], references: [id], onDelete: Cascade)\n  query             String\n  strategy          String // dense, sparse, hybrid, observation, exact_prior_chunk\n  queryFilters      Json?\n  indexVersion      String?\n  embeddingModel    String?\n  rerankerModel     String?\n  topK              Int\n  candidateCount    Int                 @default(0)\n  selectedCount     Int                 @default(0)\n  authorizationHash String?\n  status            String              @default(\"RUNNING\")\n  durationMs        Int?\n  metrics           Json? // scores, cache hit, tokenizer, retrieval config\n  createdAt         DateTime            @default(now())\n  hits              AgentRetrievalHit[]\n\n  @@index([turnId, createdAt])\n}\n\nmodel AgentRetrievalHit {\n  id                    String                 @id @default(cuid())\n  retrievalRunId        String\n  retrievalRun          AgentRetrievalRun      @relation(fields: [retrievalRunId], references: [id], onDelete: Cascade)\n  chunkId               String?\n  chunk                 MedicalDocumentChunk?  @relation(fields: [chunkId], references: [id], onDelete: SetNull)\n  chunkStableId         String // historical stable ID; authorization checked before use\n  versionStableId       String?\n  sourceObjectIds       Json?\n  sourceRefs            Json? // page numbers / bboxes / source evidence references\n  contentSha256         String\n  candidateRank         Int\n  finalRank             Int?\n  denseScore            Float?\n  sparseScore           Float?\n  hybridScore           Float?\n  rerankScore           Float?\n  includedInPrompt      Boolean                @default(false)\n  citedInAnswer         Boolean                @default(false)\n  reviewRequired        Boolean                @default(false)\n  authorizedAtRetrieval Boolean                @default(false)\n  excludedReason        String?\n  createdAt             DateTime               @default(now())\n  citations             AgentMessageCitation[]\n\n  @@unique([retrievalRunId, candidateRank])\n  @@index([chunkId])\n}\n\nmodel AgentMessageCitation {\n  id                String             @id @default(cuid())\n  messageId         String\n  message           AgentMessage       @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  retrievalHitId    String?\n  retrievalHit      AgentRetrievalHit? @relation(fields: [retrievalHitId], references: [id], onDelete: SetNull)\n  label             String\n  claimSpan         Json? // answer character range or quote range\n  chunkStableId     String?\n  documentVersionId String?\n  sourceObjectId    String?\n  pageNumber        Int?\n  sourceRefs        Json? // crop/rectangle/page, reviewed confidence\n  contentSha256     String?\n  reviewRequired    Boolean            @default(false)\n  revokedAt         DateTime?\n  createdAt         DateTime           @default(now())\n\n  @@index([messageId])\n  @@index([chunkStableId])\n  @@index([documentVersionId])\n}\n\nmodel AgentToolCall {\n  id           String         @id @default(cuid())\n  threadId     String\n  thread       AgentThread    @relation(fields: [threadId], references: [id], onDelete: Cascade)\n  turnId       String\n  turn         AgentTurn      @relation(fields: [turnId], references: [id], onDelete: Cascade)\n  toolCallId   String\n  toolName     String\n  actionType   String?\n  riskLevel    String?\n  inputJson    Json // validated, scoped arguments; never trust LLM IDs\n  inputSha256  String\n  resultJson   Json? // sanitized, authorized, bounded output only\n  resultSha256 String?\n  status       String         @default(\"PROPOSED\")\n  approvalId   String?        @unique\n  approval     AgentApproval? @relation(fields: [approvalId], references: [id], onDelete: SetNull)\n  errorCode    String?\n  durationMs   Int?\n  startedAt    DateTime       @default(now())\n  completedAt  DateTime?\n\n  @@unique([threadId, toolCallId])\n  @@index([turnId, startedAt])\n  @@index([status])\n}\n\nmodel AgentModelCall {\n  id                String      @id @default(cuid())\n  threadId          String\n  thread            AgentThread @relation(fields: [threadId], references: [id], onDelete: Cascade)\n  turnId            String?\n  turn              AgentTurn?  @relation(fields: [turnId], references: [id], onDelete: SetNull)\n  purpose           String // answer, rewrite, classification, embedding, vision, rerank\n  provider          String\n  model             String\n  modelVersion      String?\n  promptVersion     String?\n  requestSha256     String?\n  responseSha256    String?\n  promptTokens      Int?\n  completionTokens  Int?\n  totalTokens       Int?\n  latencyMs         Int?\n  providerRequestId String?\n  traceId           String?\n  retryCount        Int         @default(0)\n  fallbackFrom      String?\n  privacyPolicyRef  String?\n  status            String      @default(\"RUNNING\")\n  errorCode         String?\n  usageMetadata     Json?\n  createdAt         DateTime    @default(now())\n  completedAt       DateTime?\n\n  @@index([threadId, createdAt])\n  @@index([provider, model, createdAt])\n}\n\n// -----------------------------------------------------------------------------\n// Human approval: durable 60-second proposal and separate execution state\n// -----------------------------------------------------------------------------\n\nmodel AgentApproval {\n  id                      String               @id @default(cuid())\n  threadId                String\n  thread                  AgentThread          @relation(fields: [threadId], references: [id], onDelete: Cascade)\n  toolCallId              String\n  requestedByUserId       String\n  requestedBy             User                 @relation(\"AgentApprovalRequester\", fields: [requestedByUserId], references: [id], onDelete: Restrict)\n  approvedByUserId        String?\n  decidedBy               User?                @relation(\"AgentApprovalDecider\", fields: [approvedByUserId], references: [id], onDelete: SetNull)\n  actionType              String\n  riskLevel               AgentActionRiskLevel\n  title                   String\n  summary                 String\n  reason                  String\n  parameters              Json\n  payloadHash             String\n  idempotencyKey          String               @unique\n  status                  AgentApprovalStatus  @default(PENDING)\n  executionStatus         AgentExecutionStatus @default(NOT_STARTED)\n  createdAt               DateTime             @default(now())\n  expiresAt               DateTime\n  decidedAt               DateTime?\n  decisionReason          String?\n  executedAt              DateTime?\n  completedAt             DateTime?\n  executionResult         Json? // safe non-PHI outcome code and affected IDs\n  executionLeaseExpiresAt DateTime?\n  executionAttempts       Int                  @default(0)\n  lastErrorCode           String?\n  updatedAt               DateTime             @updatedAt\n  toolInvocation          AgentToolCall?\n\n  @@unique([threadId, toolCallId])\n  @@index([requestedByUserId, status, expiresAt])\n  @@index([status, executionStatus])\n  @@index([executionStatus, executionLeaseExpiresAt])\n}\n"
}

